import{_ as a,a as r,c as n,ac as t}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"C++ 原生边界排错：符号、释放器与异常政策","description":"按链接、调用和销毁阶段定位C库宿主的缺符号、错误释放器与noexcept终止。","frontmatter":{"title":"C++ 原生边界排错：符号、释放器与异常政策","description":"按链接、调用和销毁阶段定位C库宿主的缺符号、错误释放器与noexcept终止。","showdocs":{"topics":[{"id":"cpp","title":"C++","link":"/topics/cpp/"}],"kind":"排错","scope":"general","audience":"general","group":"语言与开发","seriesTitle":"C++ 原生边界：C ABI 与 RAII","summary":"按链接、调用和销毁阶段定位C库宿主的缺符号、错误释放器与noexcept终止。","status":"active","related":[{"title":"C++ 迭代器、区间与容器修改","link":"/programming/cpp/base/basic/iterators-algorithms","kind":"知识专题","scope":"general","audience":"general"},{"title":"C++ 对象生存期、RAII 与移动","link":"/programming/cpp/base/basic/ownership-moves","kind":"知识专题","scope":"general","audience":"general"},{"title":"C++ 泛型事务、异常保证与并发所有权","link":"/programming/cpp/base/advanced/generic-concurrency","kind":"知识专题","scope":"general","audience":"general"},{"title":"C++ 基础：从编译运行到函数与对象","link":"/programming/cpp/base/basic/c%2B%2B","kind":"知识专题","scope":"general","audience":"general"},{"title":"C++ 首批课程：值语义、RAII与库存汇总项目","link":"/programming/cpp/base/intermediate/foundations","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"C++ 完整实践：RAII 宿主连接 POSIX C 库 · C++原生项目怎样判断构建与运行边界至资料与适用边界","link":"/programming/cpp/plus/practice/abi-application-part-02"},"next":{"text":"C++ 泛型事务、异常保证与并发所有权","link":"/programming/cpp/base/advanced/generic-concurrency"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"C++ 完整实践：RAII 宿主连接 POSIX C 库 · C++原生项目怎样判断构建与运行边界至资料与适用边界","link":"/programming/cpp/plus/practice/abi-application-part-02"},"next":{"text":"C++ 泛型事务、异常保证与并发所有权","link":"/programming/cpp/base/advanced/generic-concurrency"}},"headers":[],"relativePath":"programming/cpp/plus/troubleshooting/abi-diagnostics.md","filePath":"programming/cpp/plus/troubleshooting/abi-diagnostics.md"}'),p={name:"programming/cpp/plus/troubleshooting/abi-diagnostics.md"};function i(o,e,c,s,l,m){return r(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="c-原生边界排错-符号、释放器与异常政策" tabindex="-1">C++ 原生边界排错：符号、释放器与异常政策 <a class="header-anchor" href="#c-原生边界排错-符号、释放器与异常政策" aria-label="Permalink to &quot;C++ 原生边界排错：符号、释放器与异常政策&quot;">​</a></h1><p>前置：extern C、unique_ptr自定义删除器和异常展开。排查用到的scan.h与main.cpp在<a href="/programming/cpp/plus/practice/abi-application#source">RAII宿主完整工程</a>。</p><p>核对句柄边界时可记录三列：阶段、交出的对象、失败发生时的拥有者。链接器无法找到定义发生在 <code>main</code> 之前，<code>scan_run</code> 返回错误发生在独占指针已经接管之后，两个问题需要不同的证据。</p><p>专题入口：<a href="/programming/cpp/native-interop#part-1">C++ C ABI 边界：链接、不透明句柄与错误值</a> · <a href="/programming/cpp/native-interop#part-2">C++ 原生资源所有权：接管、析构与借用</a> · <a href="/programming/cpp/plus/practice/abi-application">C++ 完整实践：RAII 宿主连接 POSIX C 库</a> · <a href="/programming/cpp/plus/troubleshooting/abi-diagnostics">C++ 原生边界排错：符号、释放器与异常政策</a></p><h2 id="symbols" tabindex="-1">C++链接C库出现undefined reference怎么查 <a class="header-anchor" href="#symbols" aria-label="Permalink to &quot;C++链接C库出现undefined reference怎么查 {#symbols}&quot;">​</a></h2><p>先确认库确实包含 scan.c 的定义、宿主包含同一个 scan.h，再检查架构、链接命令与名称修饰。把头声明随意复制到 main.cpp 可能丢失 extern C 或参数类型，造成编译可过但链接失败甚至调用协议不匹配。</p><p>头文件缺失属于预处理/编译问题；undefined reference 属于链接；启动后坏指针是运行时契约问题。不能把这三类错误都归咎于“库版本不对”。优先回到 CMake 中两种语言的分离编译与目标依赖。</p><h2 id="double-free" tabindex="-1">C++句柄重复释放或崩溃怎么查 <a class="header-anchor" href="#double-free" aria-label="Permalink to &quot;C++句柄重复释放或崩溃怎么查 {#double-free}&quot;">​</a></h2><p>为每个句柄画出唯一拥有者和每次销毁点，检查是否同时手动 scan_destroy 和自动删除器清理。由 C 库 calloc 创建的对象不能用 delete；即使用 free 释放外壳也遗漏路径和 mutex 清理。必须配库提供的删除器。</p><p>把 get 返回值构造成第二个 unique_ptr 同样造成双拥有者；对象析构后缓存的借用指针也失效。ASan 可以帮助定位已发生的问题，但调用边界的所有权规则必须先明确。</p><h2 id="exceptions" tabindex="-1">C++把整个C包装器设为noexcept会怎样 <a class="header-anchor" href="#exceptions" aria-label="Permalink to &quot;C++把整个C包装器设为noexcept会怎样 {#exceptions}&quot;">​</a></h2><p>check 本来会抛 system_error；如果把调用它的整个业务函数标 noexcept，异常离开时会触发 terminate，main 的 catch 无法恢复。noexcept 是对外承诺，不是“请编译器忽略错误”的开关。</p><p>只让真正不通过异常失败的删除器保留 noexcept，业务失败继续由宿主捕获。若未来实现 C 可调用入口，必须在入口内捕获并返回错误码；给入口加 noexcept 而不捕获，只会把本可报告的错误变为进程终止。</p><h2 id="abi-change" tabindex="-1">C++升级C库后还能否直接复用旧产物 <a class="header-anchor" href="#abi-change" aria-label="Permalink to &quot;C++升级C库后还能否直接复用旧产物 {#abi-change}&quot;">​</a></h2><p>本项目只承诺源码层边界设计，ABI 兼容仍取决于符号、调用约定、参数布局和运行库。改公开参数或结构、跨架构复制产物都会破坏兼容；不透明句柄减少布局暴露，不能自动解决所有变化。</p><p>当前选择同工具链全量重建静态库和宿主。若将来发行动态库，应制定版本化接口和兼容测试，再决定哪些变更允许替换；不能以“extern C 没有名称修饰”为由跨平台直接复用旧库。</p><h2 id="exercise" tabindex="-1">独立练习 <a class="header-anchor" href="#exercise" aria-label="Permalink to &quot;独立练习 {#exercise}&quot;">​</a></h2><p>链接失败与删除器错误分别在哪个阶段出现？给check外层加noexcept是否能改善错误报告？</p><details class="details custom-block"><summary>参考解答与检查条件</summary><p>符号解析失败在链接，删除器错误在运行资源清理。noexcept会让逃出函数的system_error触发terminate，损失main捕获机会；应保持业务可抛而析构不抛。它不会把数组越界等未定义行为自动转换成异常。</p></details><h2 id="sources" tabindex="-1">资料与适用边界 <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;资料与适用边界 {#sources}&quot;">​</a></h2><p>2026-10-17 核对 <a href="https://man7.org/linux/man-pages/man2/read.2.html" target="_blank" rel="noopener noreferrer">Linux read 手册</a>、<a href="https://man7.org/linux/man-pages/man2/write.2.html" target="_blank" rel="noopener noreferrer">write 手册</a>、<a href="https://man7.org/linux/man-pages/man2/close.2.html" target="_blank" rel="noopener noreferrer">close 的平台差异</a>、<a href="https://man7.org/linux/man-pages/man3/pthread_create.3.html" target="_blank" rel="noopener noreferrer">pthread_create</a>、<a href="https://man7.org/linux/man-pages/man3/pthread_join.3.html" target="_blank" rel="noopener noreferrer">pthread_join</a> 与 <a href="https://man7.org/linux/man-pages/man3/pthread_mutex_lock.3p.html" target="_blank" rel="noopener noreferrer">POSIX mutex 规范镜像</a>。Linux 手册中的实现差异不直接推广为 macOS 实测结果。工程由 <a href="https://cmake.org/cmake/help/v3.20/module/FindThreads.html" target="_blank" rel="noopener noreferrer">CMake FindThreads</a> 提供线程目标，构建期会检查平台需要哪些编译和链接设置。</p><p>C++ 链接与拥有关系参照 <a href="https://en.cppreference.com/w/cpp/language/language_linkage.html" target="_blank" rel="noopener noreferrer">cppreference language linkage</a>、<a href="https://en.cppreference.com/w/cpp/memory/unique_ptr.html" target="_blank" rel="noopener noreferrer">unique_ptr</a>；中文核对 <a href="https://learn.microsoft.com/zh-cn/cpp/cpp/extern-cpp?view=msvc-170" target="_blank" rel="noopener noreferrer">Microsoft extern 说明</a>，仅引用语言链接概念，不套用其 Windows 编译开关。文章采用独立组织的边界与失败推演，外链用于溯源，必要答案已在正文。</p>',22)])])}const d=a(p,[["render",i]]);export{h as __pageData,d as default};
